import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.BgftbQsK.js";const h=JSON.parse('{"title":"Installation & Disk Partitioning","description":"Complete guide to disk partitioning for Ubuntu Server including partition layout, filesystem types (ext4, FAT32, swap), and step-by-step installer instructions.","frontmatter":{"title":"Installation & Disk Partitioning","order":2,"description":"Complete guide to disk partitioning for Ubuntu Server including partition layout, filesystem types (ext4, FAT32, swap), and step-by-step installer instructions.","head":[["meta",{"name":"og:title","content":"Installation & Disk Partitioning | Ubuntu Home Lab Server"}],["meta",{"property":"og:description","content":"Complete guide to disk partitioning for Ubuntu Server including partition layout, filesystem types (ext4, FAT32, swap), and step-by-step installer instructions."}]]},"headers":[],"relativePath":"chapters/02-installation-disk-partitioning.md","filePath":"chapters/02-installation-disk-partitioning.md","lastUpdated":null}'),n={name:"chapters/02-installation-disk-partitioning.md"};function i(r,e,l,p,d,c){return s(),a("div",null,[...e[0]||(e[0]=[o(`<h2 id="understanding-disk-partitioning-—-the-why" tabindex="-1">Understanding Disk Partitioning — The Why <a class="header-anchor" href="#understanding-disk-partitioning-—-the-why" aria-label="Permalink to &quot;Understanding Disk Partitioning — The Why&quot;">​</a></h2><p>Partitioning means dividing your physical disk into separate logical sections. Each section acts as an independent disk with its own filesystem. Here&#39;s why this matters for a server:</p><p><strong>Imagine this scenario:</strong> You have one big <code>/</code> partition. Your Docker logs fill up the disk. Now your entire system crashes because there&#39;s no space for anything — not even for SSH to write its temporary files. You&#39;re locked out.</p><p>With separate partitions:</p><ul><li>Docker logs fill up <code>/var</code> → only <code>/var</code> is full</li><li>Your OS, SSH, and other services still work fine</li><li>You SSH in, clean the logs, and continue</li></ul><p>This is why separating <code>/var</code>, <code>/home</code>, <code>/srv</code>, and <code>/data</code> is professional practice, not just preference.</p><h2 id="your-partition-layout-explained" tabindex="-1">Your Partition Layout Explained <a class="header-anchor" href="#your-partition-layout-explained" aria-label="Permalink to &quot;Your Partition Layout Explained&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Samsung NVMe 500GB (nvme0n1)</span></span>
<span class="line"><span>├── /boot/efi   512MB  FAT32   ← UEFI bootloader lives here</span></span>
<span class="line"><span>├── /boot         1GB  ext4    ← Linux kernel &amp; initrd images</span></span>
<span class="line"><span>├── /             80GB ext4    ← OS root: system binaries, configs</span></span>
<span class="line"><span>├── /var          50GB ext4    ← Variable data: logs, Docker, apt cache</span></span>
<span class="line"><span>├── /home         50GB ext4    ← Your personal files, SSH keys, dotfiles</span></span>
<span class="line"><span>├── /srv          80GB ext4    ← Service data: your NestJS apps, websites</span></span>
<span class="line"><span>├── swap          16GB swap    ← Virtual RAM (= your physical RAM size)</span></span>
<span class="line"><span>└── /data        ~188GB ext4   ← Datasets, ML models, backups</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h3 id="what-goes-where" tabindex="-1">What Goes Where? <a class="header-anchor" href="#what-goes-where" aria-label="Permalink to &quot;What Goes Where?&quot;">​</a></h3><p><strong><code>/boot/efi</code></strong> — The UEFI firmware needs a FAT32 partition to find the bootloader. This is non-negotiable on modern UEFI systems. 512MB is plenty (it only stores a few MB of bootloader files, but we give it 512MB for safety — this was literally the bug you hit during installation: the old partition was too small).</p><p><strong><code>/boot</code></strong> — Contains the Linux kernel (<code>vmlinuz</code>) and initial RAM disk (<code>initrd</code>). When you run <code>apt upgrade</code>, new kernel versions are placed here. 1GB is enough for several kernel versions.</p><p><strong><code>/</code> (root)</strong> — The operating system itself. All system binaries (<code>/usr/bin</code>), system configs (<code>/etc</code>), libraries (<code>/lib</code>). 80GB is generous — the base system uses ~5GB, but you want room for packages, pip installs, and npm globals.</p><p><strong><code>/var</code></strong> — Everything that changes frequently at runtime. This is the most important partition to separate:</p><ul><li><code>/var/lib/docker</code> — All Docker images, containers, volumes (can easily reach 20-40GB)</li><li><code>/var/lib/postgresql</code> — If you run Postgres outside Docker</li><li><code>/var/log</code> — System and application logs</li><li><code>/var/cache/apt</code> — Downloaded packages</li></ul><p><strong><code>/home</code></strong> — Your user&#39;s home directory. Projects you clone with git, your <code>.bashrc</code>, <code>.ssh</code> keys, NVM, Python virtualenvs. Keeping it separate means you can reinstall the OS without losing your files.</p><p><strong><code>/srv</code></strong> — Conventionally for &quot;served&quot; data — web apps, API code running as services. Keeping this separate from <code>/home</code> is good practice for production-like setups.</p><p><strong><code>swap</code></strong> — Acts as overflow RAM. When your 16GB RAM fills up, the kernel moves less-used memory pages here. For AI workloads that might spike RAM (loading a large model), having swap prevents OOM (Out of Memory) kills. Match it to your RAM size: 16GB.</p><p><strong><code>/data</code></strong> — Your personal big storage: the OpenFoodFacts CSV (2GB+), trained models, Parquet files, exports. Keeping this separate makes it easy to mount on the HDD later or expand.</p><h2 id="filesystem-types-explained" tabindex="-1">Filesystem Types Explained <a class="header-anchor" href="#filesystem-types-explained" aria-label="Permalink to &quot;Filesystem Types Explained&quot;">​</a></h2><p><strong>ext4</strong> — The standard Linux filesystem. Mature, stable, supports files up to 16TB, journaling (crash recovery). Use this for everything except EFI.</p><p><strong>FAT32</strong> — Required for EFI partition. UEFI firmware can only read FAT32.</p><p><strong>swap</strong> — Not really a filesystem — it&#39;s raw space the kernel uses as virtual memory.</p><h2 id="creating-partitions-in-the-ubuntu-installer" tabindex="-1">Creating Partitions in the Ubuntu Installer <a class="header-anchor" href="#creating-partitions-in-the-ubuntu-installer" aria-label="Permalink to &quot;Creating Partitions in the Ubuntu Installer&quot;">​</a></h2><p>In the installer&#39;s &quot;Storage configuration&quot; screen:</p><ol><li>Select the <strong>free space</strong> under your Samsung NVMe → Enter → <strong>Add GPT Partition</strong></li><li>For each partition, fill in: <ul><li><strong>Size</strong>: exact size (e.g., <code>512M</code>, <code>1G</code>, <code>80G</code>)</li><li><strong>Format</strong>: <code>fat32</code>, <code>ext4</code>, or <code>swap</code></li><li><strong>Mount</strong>: <code>/boot/efi</code>, <code>/boot</code>, <code>/</code>, <code>/var</code>, <code>/home</code>, <code>/srv</code>, <code>/data</code></li></ul></li><li>For swap: Format = <code>swap</code>, no mount point needed</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>Important:</strong> Create them in order from top to bottom. The installer assigns partition numbers sequentially (nvme0n1p1, p2, p3...).</p></div>`,26)])])}const g=t(n,[["render",i]]);export{h as __pageData,g as default};
